static const char *btr_lookup(const char *s, int l)
{
    if (!lang_ok(l)) return 0;
    for (unsigned i = 0; i < sizeof BTR / sizeof BTR[0]; i++) if (!strcmp(BTR[i][0], s)) return BTR[i][1 + l];
    return 0;
}
